import React, { useEffect, useState } from 'react';
import {
  Box, Card, CardContent, Grid, TextField, Button,
  MenuItem, Typography, Divider, CircularProgress,
} from '@mui/material';
import SaveIcon   from '@mui/icons-material/Save';
import { useNavigate, useParams } from 'react-router-dom';
import toast from 'react-hot-toast';
import api from '../../api/axios';
import PageHeader from '../../components/PageHeader';

const EMPTY = {
  numberPlate: '', model: '', purchaseAmount: '', purchaseDate: '',
  purchaseFrom: '', saledAmount: '', saledDate: '', purchasedById: '',
};

export default function CarPurchaseForm() {
  const { id }    = useParams();
  const navigate  = useNavigate();
  const isEdit    = Boolean(id);
  const [form,    setForm]   = useState(EMPTY);
  const [users,   setUsers]  = useState([]);
  const [saving,  setSaving] = useState(false);
  const [errors,  setErrors] = useState({});

  useEffect(() => {
    api.get('/users').then(r => setUsers(r.data.data || [])).catch(() => {});
    if (isEdit) {
      api.get(`/car-purchases/${id}`).then(r => {
        const d = r.data.data;
        setForm({
          numberPlate:    d.numberPlate    || '',
          model:          d.carModel       || '',
          purchaseAmount: d.purchaseAmount || '',
          purchaseDate:   d.purchaseDate   || '',
          purchaseFrom:   d.purchaseFrom   || '',
          saledAmount:    d.saledAmount    || '',
          saledDate:      d.saledDate      || '',
          purchasedById:  d.purchasedById  || '',
        });
      }).catch(e => toast.error(e.message));
    }
  }, [id]);

  const validate = () => {
    const e = {};
    if (!form.numberPlate)   e.numberPlate   = 'Number plate is required';
    if (!form.model)         e.model         = 'Car model is required';
    if (!form.purchaseAmount || form.purchaseAmount <= 0)
                             e.purchaseAmount = 'Valid purchase amount required';
    if (!form.purchaseDate)  e.purchaseDate  = 'Purchase date is required';
    if (!form.purchaseFrom)  e.purchaseFrom  = 'Purchase from is required';
    if (!form.purchasedById) e.purchasedById = 'Please select a user';
    setErrors(e);
    return Object.keys(e).length === 0;
  };

  const handleChange = e => {
    const { name, value } = e.target;
    setForm(prev => ({ ...prev, [name]: value }));
    if (errors[name]) setErrors(prev => ({ ...prev, [name]: '' }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validate()) return;
    setSaving(true);
    try {
      const payload = {
        ...form,
        purchaseAmount: parseFloat(form.purchaseAmount),
        saledAmount:    form.saledAmount ? parseFloat(form.saledAmount) : null,
        purchasedById:  parseInt(form.purchasedById),
        saledDate:      form.saledDate || null,
      };
      if (isEdit) {
        await api.put(`/car-purchases/${id}`, payload);
        toast.success('Car purchase updated!');
      } else {
        await api.post('/car-purchases', payload);
        toast.success('Car purchase created!');
      }
      navigate('/car-purchases');
    } catch (err) {
      toast.error(err.message);
    } finally {
      setSaving(false);
    }
  };

  const Field = ({ label, name, type = 'text', required }) => (
    <TextField
      fullWidth label={label} name={name} type={type}
      value={form[name]} onChange={handleChange}
      required={required}
      error={Boolean(errors[name])}
      helperText={errors[name]}
      InputLabelProps={type === 'date' ? { shrink: true } : undefined}
    />
  );

  return (
    <Box>
      <PageHeader
        title={isEdit ? 'Edit Car Purchase' : 'Add Car Purchase'}
        backTo="/car-purchases"
      />

      <Card sx={{ maxWidth: 800 }}>
        <CardContent>
          <form onSubmit={handleSubmit}>

            {/* Purchase Info */}
            <Typography variant="subtitle2" color="primary" fontWeight={700}
                        textTransform="uppercase" letterSpacing={1} mb={2}>
              Purchase Information
            </Typography>
            <Grid container spacing={2} mb={3}>
              <Grid item xs={12} sm={6}><Field label="Number Plate"   name="numberPlate"    required /></Grid>
              <Grid item xs={12} sm={6}><Field label="Car Model"      name="model"          required /></Grid>
              <Grid item xs={12} sm={6}><Field label="Purchase From"  name="purchaseFrom"   required /></Grid>
              <Grid item xs={12} sm={6}><Field label="Purchase Date"  name="purchaseDate"   type="date" required /></Grid>
              <Grid item xs={12} sm={6}><Field label="Purchase Amount" name="purchaseAmount" type="number" required /></Grid>
              <Grid item xs={12} sm={6}>
                <TextField
                  select fullWidth label="Purchased By" name="purchasedById"
                  value={form.purchasedById} onChange={handleChange}
                  required error={Boolean(errors.purchasedById)}
                  helperText={errors.purchasedById}
                >
                  <MenuItem value="">Select User</MenuItem>
                  {users.map(u => (
                    <MenuItem key={u.id} value={u.id}>{u.name}</MenuItem>
                  ))}
                </TextField>
              </Grid>
            </Grid>

            <Divider sx={{ mb: 3 }} />

            {/* Sale Info */}
            <Typography variant="subtitle2" color="primary" fontWeight={700}
                        textTransform="uppercase" letterSpacing={1} mb={2}>
              Sale Information <Typography component="span" variant="caption"
                                           color="text.secondary">(Optional)</Typography>
            </Typography>
            <Grid container spacing={2} mb={3}>
              <Grid item xs={12} sm={6}><Field label="Sale Amount" name="saledAmount" type="number" /></Grid>
              <Grid item xs={12} sm={6}><Field label="Sale Date"   name="saledDate"   type="date" /></Grid>
            </Grid>

            {/* Actions */}
            <Box sx={{ display: 'flex', gap: 2 }}>
              <Button type="submit" variant="contained" startIcon={
                saving ? <CircularProgress size={16} color="inherit" /> : <SaveIcon />
              } disabled={saving}>
                {saving ? 'Saving...' : isEdit ? 'Update' : 'Save'}
              </Button>
              <Button variant="outlined" onClick={() => navigate('/car-purchases')}>
                Cancel
              </Button>
            </Box>
          </form>
        </CardContent>
      </Card>
    </Box>
  );
}
